package behavioral.observer.projects.stockmarket;

import behavioral.observer.projects.stockmarket.async.NotificationExecutor;
import behavioral.observer.projects.stockmarket.exchange.StockExchange;
import behavioral.observer.projects.stockmarket.observer.Trader;
import behavioral.observer.projects.stockmarket.service.MarketDataService;
import behavioral.observer.projects.stockmarket.subject.Stock;

public class Main {

    public static void main(String[] args) {

        // Create stock exchange
        StockExchange exchange = new StockExchange();

        // Create stocks
        Stock apple = new Stock(
                "AAPL",
                200
        );

        Stock tesla = new Stock(
                "TSLA",
                300
        );

        // Add stocks to exchange
        exchange.addStock(apple);
        exchange.addStock(tesla);

        Trader shubhi = new Trader("Shubhi");

        Trader prateek = new Trader("Prateek");

        // Subscribe traders
        apple.subscribe(shubhi);

        apple.subscribe(prateek);

        tesla.subscribe(prateek);

        // Create stock update threads
        Thread appleThread  = new Thread(
                new MarketDataService(
                        apple
                )
        );

        Thread teslaThread = new Thread(
                new MarketDataService(
                        tesla
                )
        );

        appleThread.start();

        teslaThread.start();

        try {
            appleThread.join();
            teslaThread.join();

        } catch (InterruptedException ex) {
            ex.printStackTrace();
        }

        // Shutdown executor service
        NotificationExecutor.shutdown();

        System.out.println(
                "\nStock Market System Stopped"
        );
    }
}

package behavioral.observer.projects.stockmarket.async;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class NotificationExecutor {

    private static final
    ExecutorService executorService = Executors.newFixedThreadPool(5);

    public static ExecutorService getExecutorService() {
        return executorService;
    }
    public static void shutdown() {
        executorService.shutdown();
    }
}

package behavioral.observer.projects.stockmarket.exchange;

import behavioral.observer.projects.stockmarket.subject.Stock;
import java.util.HashMap;
import java.util.Map;

public class StockExchange {

    private final Map<String, Stock> stocks;

    public StockExchange() {
        this.stocks = new HashMap<>();
    }

    public void addStock(Stock stock) {
        stocks.put(stock.getName(), stock);
    }

    public Stock getStock(String name) {
        return stocks.get(name);
    }
}

package behavioral.observer.projects.stockmarket.observer;

public interface IObserver {
    void update(String stockName, double price);
}

package behavioral.observer.projects.stockmarket.observer;

public class Trader implements IObserver {
    private final String name;

    public Trader(String name) {
        this.name = name;
    }

    @Override
    public void update(String stockName, double price) {
        System.out.println(
            String.format(
                "[%s] -> Trader %s notified. Stock: %s, Price: %.2f",
                Thread.currentThread().getName(),
                name,
                stockName,
                price
            )
        );
    }

}

package behavioral.observer.projects.stockmarket.service;

import behavioral.observer.projects.stockmarket.subject.Stock;
import java.util.Random;

public class MarketDataService implements Runnable {

    private final Stock stock;

    public MarketDataService(Stock stock) {
        this.stock = stock;
    }

    @Override
    public void run() {
        Random random = new Random();
        for(int i = 0; i < 5; i++) {
            double newPrice =stock.getPrice() + random.nextInt(20);
            stock.setPrice(newPrice);
            try {
                Thread.sleep(2000);
            } catch (InterruptedException ex) {
                ex.printStackTrace();
            }
        }
    }
}

package behavioral.observer.projects.stockmarket.subject;

